        BAR_2 = rcall(K("Fmt"), :max, Any[2.5, rcall(K("Fmt"), :min, Any[4.5, mul(CELL_0, 0.075)])])
        BASE_2 = mul(HEADW_2, 0.45)
        TIP_2 = mul(HEADW_2, 0.55)
        LEN_2 = sub(REACH_2, BASE_2)
        SEEN_2 = sub(TIP_2, rdiv(BAR_2, 0.84))
        for sd_3 in items(rget(l_2, :sides))
          px_3 = rinvoke(X_0, Any[k__2, rget(sd_3, :at)])
          rcall(s_0, :stroke_style, Any[(j"rgba(" * str(rget(sd_3, :ink)) * j"," * str(rget(ink_0, :behind)) * j")")])
          rcall(s_0, :line_width, Any[BAR_2])
          rget(s_0, :begin_path)
          rcall(s_0, :move_to, Any[sub(px_3, mul(rget(sd_3, :sign), (add(BASE_2, LEN_2)))), y_1])
          rcall(s_0, :line_to, Any[sub(px_3, mul(rget(sd_3, :sign), BASE_2)), y_1])
          rget(s_0, :stroke)
          rcall(s_0, :stroke_style, Any[(j"rgba(" * str(rget(sd_3, :ink)) * j"," * str(rget(ink_0, :front)) * j")")])
          rget(s_0, :begin_path)
          rcall(s_0, :move_to, Any[px_3, y_1])
          rcall(s_0, :line_to, Any[add(px_3, mul(rget(sd_3, :sign), (add(SEEN_2, LEN_2)))), y_1])
          rget(s_0, :stroke)
        end
        for sd_3 in items(rget(l_2, :sides))
          px_3 = rinvoke(X_0, Any[k__2, rget(sd_3, :at)])
          rcall(s_0, :fill_style, Any[(j"rgba(" * str(rget(sd_3, :ink)) * j"," * str(rget(ink_0, :head)) * j")")])
          rget(s_0, :begin_path)
          rcall(s_0, :move_to, Any[add(px_3, mul(rget(sd_3, :sign), TIP_2)), y_1])
          rcall(s_0, :line_to, Any[sub(px_3, mul(rget(sd_3, :sign), BASE_2)), sub(y_1, mul(HEADW_2, 0.42))])
          rcall(s_0, :line_to, Any[sub(px_3, mul(rget(sd_3, :sign), BASE_2)), add(y_1, mul(HEADW_2, 0.42))])
          rget(s_0, :fill)
        end
      end
    end
    nothing
  end)
end

