  end)
  statik!(c, :carries, function (self, a1::Vector{Any})
    return (let q_ = rget(rget(rget(K("Law"), :law), :header), Symbol(str((j"carries")))); q_ === nothing ? (0.0) : q_ end)
    nothing
  end)
  statik!(c, :theory, function (self, a1::Vector{Any})
    return (let q_ = rget(rget(rget(K("Law"), :law), :header), Symbol(str((j"theory")))); q_ === nothing ? ((j"G")) : q_ end)
    nothing
  end)
  statik!(c, :boost, function (self, a1::Vector{Any})
    gN_0 = arg(a1, 0); scale_0 = arg(a1, 1)
    A0_0 = rget(K("Law"), :a0)
    xs__0 = rget(rget(rget(K("Law"), :law), :columns), Symbol(str((j"gN"))))
    ys__0 = rget(rget(rget(K("Law"), :law), :columns), Symbol(str((j"g"))))
    want_0 = mul((rdiv(gN_0, scale_0)), A0_0)
    lo_0 = 0.0
    hi_0 = sub(rget(rget(K("Law"), :law), :rows), 1.0)
    if truthy(le(want_0, elem(xs__0, 0.0)))
      return mul((rdiv(elem(ys__0, 0.0), A0_0)), scale_0)
    end
    if truthy(ge(want_0, elem(xs__0, hi_0)))
      return mul((rdiv(elem(ys__0, hi_0), A0_0)), scale_0)
    end
    while truthy(gt(sub(hi_0, lo_0), 1.0))
      mid_0 = m_floor((rdiv((add(lo_0, hi_0)), 2.0)))
      if truthy(le(elem(xs__0, mid_0), want_0))
        lo_0 = mid_0
      else
        hi_0 = mid_0
      end
    end
    t_0 = rdiv((sub(m_ln(want_0), m_ln(elem(xs__0, lo_0)))), (sub(m_ln(elem(xs__0, hi_0)), m_ln(elem(xs__0, lo_0)))))
    return mul((rdiv(m_exp((add(m_ln(elem(ys__0, lo_0)), mul(t_0, (sub(m_ln(elem(ys__0, hi_0)), m_ln(elem(ys__0, lo_0)))))))), A0_0)), scale_0)
    nothing
  end)
end

