    FR_0 = rget(H_0, Symbol(str((j"frames"))))
    D_0 = rget(rget(formed_0, :columns), Symbol(str((j"density"))))
    per_scale_0 = rdiv(G_0, (rdiv(mul(2.0, elem(rget(H_0, Symbol(str((j"span")))), g_0)), elem(rget(H_0, Symbol(str((j"scale")))), g_0))))
