        cy_3 = Float64(i3)
        for i4 in 0:(ceil(Int, num(G_0)) - 1)
          cx_4 = Float64(i4)
          v_4 = elem(D_0, add(add(base_2, mul(cy_3, G_0)), cx_4))
          dx_4 = sub(add(cx_4, 0.5), mx_2)
          dy_4 = sub(add(cy_3, 0.5), my_2)
