        m_4 = arg(a5, 0)
        return (truthy(gt(total_2, 0.0)) ? (rdiv(rcall(K("Fmt"), :hypot, Any[elem(re_2, m_4), elem(im_2, m_4)]), total_2)) : (0.0))
