    end)))
    rset!(extra_0, Symbol(str((j"Y_disk"))), rget(self, :best_y))
    rset!(extra_0, Symbol(str((j"Y_bulge"))), rget(self, :best_b))
    rset!(extra_0, Symbol(str((j"D"))), rget(self, :best_d))
    rset!(extra_0, Symbol(str((j"Inc"))), rget(self, :best_i))
    rset!(extra_0, Symbol(str((j"rms0"))), rms0_0)
    rset!(extra_0, Symbol(str((j"rms1"))), rms1_0)
    rset!(extra_0, Symbol(str((j"repro"))), rget(self, :repro))
    rset!(extra_0, Symbol(str((j"stir"))), rget(K("Simulation"), :SIGMA))
    rset!(extra_0, Symbol(str((j"about"))), (j"every measured radius of every galaxy run: the laid galaxy's disc, gas and bulge pull (mass-to-light one, (km/s)^2/kpc), the circular speed at SPARC's own freedoms (v0) and at the fitted ones as the data would see them (v1), what the tracers moved at (vs); per galaxy in the header the fitted freedoms and the rms in dex"))
    rcall(K("Measure"), :save, Any[(j"galaxy.simulated"), names_0, cols_0, extra_0])
    fields_0 = make(NODE)
