      f_1 = rdiv(elem(rget(self, :best_d), j_1), elem(rget(S_0, Symbol(str((j"D")))), g_1))
      s_1 = rdiv(m_sin((rdiv(mul(elem(rget(S_0, Symbol(str((j"Inc")))), g_1), 3.141592653589793), 180.0))), m_sin((rdiv(mul(elem(rget(self, :best_i), j_1), 3.141592653589793), 180.0))))
      for i2 in 0:(ceil(Int, num(T_0)) - 1)
