    rset!(fextra_0, Symbol(str((j"about"))), (j"the laid galaxy's field on the table, every galaxy run: disc, gas and bulge at mass-to-light one, the circular speed at SPARC's freedoms (v0), at the fitted ones as the data would see them (v1), and Newton at SPARC's (vN)"))
    rcall(K("Measure"), :save, Any[(j"galaxy.fields"), fnames_0, fields_0, fextra_0])
    if truthy(rnot(m_empty(rget(self, :film_ids))))
