      rset!(sextra_0, Symbol(str((j"stars"))), rget(K("Simulation"), :FILM_STARS))
      rset!(sextra_0, Symbol(str((j"frames"))), rget(K("Simulation"), :FRAMES))
      rset!(sextra_0, Symbol(str((j"reach"))), m_map(rget(self, :film_ids), (function (a3::Vector{Any})
        g_2 = arg(a3, 0)
