      return rcall(K("Measure"), :save, Any[(j"galaxy.stars"), Any[(j"x"), (j"y")], film_0, sextra_0])
    end
    nothing
  end)
  statik!(c, :rms, function (self, a1::Vector{Any})
    xs__0 = arg(a1, 0)
    if truthy(m_empty(xs__0))
      return NaN
    end
    s_0 = 0.0
    for v_1 in items(xs__0)
      s_0 = add(s_0, mul(v_1, v_1))
    end
    return m_sqrt((rdiv(s_0, len(xs__0))))
    nothing
  end)
  statik!(c, :shape_x, function (self, a1::Vector{Any})
    i_0 = arg(a1, 0)
    return power(10.0, (add(neg(2.0), rdiv(mul(3.6, i_0), sub(rget(K("Simulation"), :SHAPE_N), 1.0)))))
    nothing
  end)
  statik!(c, :shape_edge, function (self, a1::Vector{Any})
    a_0 = arg(a1, 0)
    return rdiv(mul(15.0, a_0), rget(K("Simulation"), :SHAPE_EDGES))
    nothing
  end)
  statik!(c, :shape_mass, function (self, a1::Vector{Any})
    a_0 = arg(a1, 0)
    e0_0 = rcall(K("Simulation"), :shape_edge, Any[a_0])
    e1_0 = rcall(K("Simulation"), :shape_edge, Any[add(a_0, 1.0)])
    return sub(mul((add(1.0, e0_0)), m_exp((sub(0.0, e0_0)))), mul((add(1.0, e1_0)), m_exp((sub(0.0, e1_0)))))
    nothing
  end)
  statik!(c, :shape_tasks, function (self, a1::Vector{Any})
    out_0 = Any[]
    for i1 in 0:(ceil(Int, num(rget(K("Simulation"), :SHAPE_N))) - 1)
      i_1 = Float64(i1)
      for i2 in 0:(ceil(Int, num(rget(K("Simulation"), :SHAPE_EDGES))) - 1)
        a_2 = Float64(i2)
        for v_3 in items(Any[rcall(K("Simulation"), :shape_x, Any[i_1]), rcall(K("Simulation"), :shape_edge, Any[a_2]), rcall(K("Simulation"), :shape_edge, Any[add(a_2, 1.0)]), rget(K("Simulation"), :SHAPE_H)])
          m_push(out_0, v_3)
