      end
    end
    return out_0
    nothing
  end)
  statik!(c, :shape_of, function (self, a1::Vector{Any})
    pulls_0 = arg(a1, 0)
    return m_map(rng(rget(K("Simulation"), :SHAPE_N)), (function (a3::Vector{Any})
      i_2 = arg(a3, 0)
      s_2 = 0.0
      for i3 in 0:(ceil(Int, num(rget(K("Simulation"), :SHAPE_EDGES))) - 1)
        a_3 = Float64(i3)
        s_2 = add(s_2, mul(rcall(K("Simulation"), :shape_mass, Any[a_3]), elem(pulls_0, add(mul(i_2, rget(K("Simulation"), :SHAPE_EDGES)), a_3))))
      end
      return s_2
      nothing
    end))
    nothing
  end)
  statik!(c, :shape_at, function (self, a1::Vector{Any})
    shape_0 = arg(a1, 0); x_0 = arg(a1, 1)
    lx_0 = rcall(K("Fmt"), :log10, Any[x_0])
    u_0 = mul(rdiv((add(lx_0, 2.0)), 3.6), sub(rget(K("Simulation"), :SHAPE_N), 1.0))
    if truthy(le(u_0, 0.0))
      return rdiv(mul(elem(shape_0, 0.0), x_0), rcall(K("Simulation"), :shape_x, Any[0.0]))
    end
    if truthy(ge(u_0, sub(rget(K("Simulation"), :SHAPE_N), 1.0)))
      return mul(elem(shape_0, sub(rget(K("Simulation"), :SHAPE_N), 1.0)), power((rdiv(rcall(K("Simulation"), :shape_x, Any[sub(rget(K("Simulation"), :SHAPE_N), 1.0)]), x_0)), 2.0))
    end
    i_0 = m_floor(u_0)
    f_0 = sub(u_0, i_0)
    return add(mul(elem(shape_0, i_0), (sub(1.0, f_0))), mul(elem(shape_0, add(i_0, 1.0)), f_0))
    nothing
  end)
  statik!(c, :axis, function (self, a1::Vector{Any})
    a_0 = arg(a1, 0); i_0 = arg(a1, 1)
    return add(elem(a_0, 0.0), rdiv(mul((sub(elem(a_0, 1.0), elem(a_0, 0.0))), i_0), sub(elem(a_0, 2.0), 1.0)))
    nothing
  end)
  statik!(c, :possible_points, function (self, a1::Vector{Any})
    shape_0 = arg(a1, 0)
    out_0 = Any[]
    for i1 in 0:(ceil(Int, num(elem(rget(K("Simulation"), :MASSES), 2.0))) - 1)
      which_m_1 = Float64(i1)
      M_1 = power(10.0, rcall(K("Simulation"), :axis, Any[rget(K("Simulation"), :MASSES), which_m_1]))
      for i2 in 0:(ceil(Int, num(elem(rget(K("Simulation"), :SCALES), 2.0))) - 1)
        which_s_2 = Float64(i2)
        rd_2 = power(10.0, rcall(K("Simulation"), :axis, Any[rget(K("Simulation"), :SCALES), which_s_2]))
        for fg_3 in items(rget(K("Simulation"), :GAS))
          for wide_4 in items(rget(K("Simulation"), :GAS_WIDE))
            for fb_5 in items(rget(K("Simulation"), :BULGE))
              GM_5 = mul(rget(K("Simulation"), :G_KPC), M_1)
              disc_5 = mul(mul(GM_5, (sub(1.0, fg_3))), (sub(1.0, fb_5)))
              gas_5 = mul(GM_5, fg_3)
              bul_5 = mul(mul(GM_5, (sub(1.0, fg_3))), fb_5)
              rg_5 = mul(rd_2, wide_4)
              for i6 in 0:(ceil(Int, num(rget(K("Simulation"), :RADII))) - 1)
                k_6 = Float64(i6)
                r_6 = mul(rd_2, power(10.0, (add(neg(0.7), rdiv(mul(1.6, k_6), sub(rget(K("Simulation"), :RADII), 1.0))))))
                gN_6 = add(add(mul(rdiv(disc_5, (mul(rd_2, rd_2))), rcall(K("Simulation"), :shape_at, Any[shape_0, rdiv(r_6, rd_2)])), mul(rdiv(gas_5, (mul(rg_5, rg_5))), rcall(K("Simulation"), :shape_at, Any[shape_0, rdiv(r_6, rg_5)]))), rdiv(bul_5, (power((add(r_6, mul(rget(K("Simulation"), :BULGE_A), rd_2))), 2.0))))
                for v_7 in items(Any[0.0, r_6, gN_6, 0.0, 0.0, 0.0])
                  m_push(out_0, v_7)
                end
              end
            end
          end
        end
      end
    end
    return out_0
    nothing
  end)
  statik!(c, :binned, function (self, a1::Vector{Any})
    points_0 = arg(a1, 0); felt_0 = arg(a1, 1)
    n_0 = add(m_round((rdiv((sub(rget(K("Galaxies"), :XMAX), rget(K("Galaxies"), :XMIN))), rget(K("Simulation"), :BIN)))), 1.0)
    landed_0 = filled(n_0, 0.0)
    heights_0 = filled(n_0, 0.0)
    lo_0 = filled(n_0, NaN)
    hi_0 = filled(n_0, NaN)
    for i1 in 0:(ceil(Int, num(len(felt_0))) - 1)
      i_1 = Float64(i1)
      gN_1 = elem(points_0, add(mul(6.0, i_1), 2.0))
      g_1 = elem(felt_0, i_1)
      if truthy((truthy(gt(gN_1, 0.0)) && truthy(gt(g_1, 0.0))))
        x_1 = rcall(K("Fmt"), :log10, Any[rdiv(mul(gN_1, rget(K("Simulation"), :UNIT_G)), rget(K("Galaxies"), :A0_DATA))])
        y_1 = rcall(K("Fmt"), :log10, Any[rdiv(mul(g_1, rget(K("Simulation"), :UNIT_G)), rget(K("Galaxies"), :A0_DATA))])
        b_1 = m_round((rdiv((sub(x_1, rget(K("Galaxies"), :XMIN))), rget(K("Simulation"), :BIN))))
        if truthy((truthy(ge(b_1, 0.0)) && truthy(lt(b_1, n_0))))
          set_at!(landed_0, b_1, add(elem(landed_0, b_1), 1.0))
          set_at!(heights_0, b_1, add(elem(heights_0, b_1), y_1))
          set_at!(lo_0, b_1, (truthy(rcall(K("Fmt"), :finite, Any[elem(lo_0, b_1)])) ? (rcall(K("Fmt"), :min, Any[elem(lo_0, b_1), y_1])) : (y_1)))
          set_at!(hi_0, b_1, (truthy(rcall(K("Fmt"), :finite, Any[elem(hi_0, b_1)])) ? (rcall(K("Fmt"), :max, Any[elem(hi_0, b_1), y_1])) : (y_1)))
        end
      end
    end
    return Any[landed_0, m_map(rng(n_0), (function (a3::Vector{Any})
      b_2 = arg(a3, 0)
      return (truthy(gt(elem(landed_0, b_2), 0.0)) ? (rdiv(elem(heights_0, b_2), elem(landed_0, b_2))) : (NaN))
      nothing
    end)), lo_0, hi_0]
    nothing
  end)
  statik!(c, :save_possible, function (self, a1::Vector{Any})
    degs_0 = arg(a1, 0); a0s_0 = arg(a1, 1); bins_0 = arg(a1, 2)
    cols_0 = make(NODE)
    rset!(cols_0, Symbol(str((j"deg"))), degs_0)
    rset!(cols_0, Symbol(str((j"a0"))), a0s_0)
    extra_0 = make(NODE)
    rset!(extra_0, Symbol(str((j"bins"))), bins_0)
    rset!(extra_0, Symbol(str((j"from"))), rget(K("Galaxies"), :XMIN))
    rset!(extra_0, Symbol(str((j"step"))), rget(K("Simulation"), :BIN))
    rset!(extra_0, Symbol(str((j"axes"))), Any[(j"log M (Msun)"), rget(K("Simulation"), :MASSES), (j"log R_d (kpc)"), rget(K("Simulation"), :SCALES), (j"gas share"), rget(K("Simulation"), :GAS), (j"gas scale / R_d"), rget(K("Simulation"), :GAS_WIDE), (j"bulge share of the stars"), rget(K("Simulation"), :BULGE)])
    rset!(extra_0, Symbol(str((j"about"))), (j"every galaxy there could be, run through the same field and law, per lattice: in bins of log(g_bar / 1.2e-10), how many (galaxy, radius) land there, and log(g / 1.2e-10) - mean, lowest, highest"))
    return rcall(K("Measure"), :save, Any[(j"galaxy.possible"), Any[(j"deg"), (j"a0")], cols_0, extra_0])
    nothing
  end)
end

let c = cls("Formed", "Node")
  field!(c, :deg, nothing)
  static_field!(c, :N, (self) -> 16384.0)
  static_field!(c, :TILE, (self) -> 256.0)
  static_field!(c, :Q, (self) -> 1.2)
  static_field!(c, :STEPS, (self) -> 3000.0)
  static_field!(c, :DT, (self) -> 0.001)
  static_field!(c, :FRAMES, (self) -> 120.0)
  static_field!(c, :GRID, (self) -> 128.0)
