  static_field!(c, :SPAN, (self) -> 6.0)
  static_field!(c, :RINGS, (self) -> 48.0)
  static_field!(c, :DISCS, (self) -> Any[Any[10.7, 3.0], Any[9.3, 2.0]])
  static_field!(c, :WHAT, (self) -> Any[(j"a bright disc"), (j"a dwarf")])
  field!(c, :a0, (self) -> rdiv(rcall(K("Galaxies"), :a0_at, Any[rget(self, :deg)]), rget(K("Simulation"), :UNIT_G)))
  field!(c, :newton, (self) -> false)
  getter!(c, :scale_a0, function (self, a1::Vector{Any})
