  end)
  method!(c, :GM, function (self, a1::Vector{Any})
    g_0 = arg(a1, 0)
    return mul(rget(K("Simulation"), :G_KPC), power(10.0, elem(elem(rget(K("Formed"), :DISCS), g_0), 0.0)))
    nothing
  end)
  method!(c, :scale, function (self, a1::Vector{Any})
    g_0 = arg(a1, 0)
    return elem(elem(rget(K("Formed"), :DISCS), g_0), 1.0)
    nothing
  end)
