        return rcall(K("Shaded"), :wgsl, Any[x_2, names_0, bound_0])
        nothing
      end))
      summed_0 = m_join(parts_0, (j" + "))
      return (j"(" * str(summed_0) * j")")
    end
    if truthy(eq(k_0, (j"mul")))
      parts_0 = m_map(rget(e_0, :of), (function (a3::Vector{Any})
        x_2 = arg(a3, 0)
        return rcall(K("Shaded"), :wgsl, Any[x_2, names_0, bound_0])
        nothing
      end))
      multiplied_0 = m_join(parts_0, (j" * "))
      return (j"(" * str(multiplied_0) * j")")
    end
    if truthy(eq(k_0, (j"pow")))
      base_0 = rcall(K("Shaded"), :wgsl, Any[rget(e_0, :base), names_0, bound_0])
      if truthy(eq(rget(rget(e_0, :power), :kind), (j"num")))
        n_0 = rget(rget(e_0, :power), :value)
        if truthy(eq(n_0, 0.5))
          return (j"sqrt(" * str(base_0) * j")")
        end
        if truthy((truthy(eq(n_0, m_floor(n_0))) && truthy(le(m_abs(n_0), 64.0))))
          return (j"powi(" * str(base_0) * j", " * str(m_round(n_0)) * j")")
        end
        return (j"pow(" * str(base_0) * j", " * str(rcall(K("Shaded"), :literal, Any[n_0])) * j")")
      end
      return (j"pow(" * str(base_0) * j", " * str(rcall(K("Shaded"), :wgsl, Any[rget(e_0, :power), names_0, bound_0])) * j")")
    end
    if truthy(eq(k_0, (j"log")))
