  end)
  statik!(c, :helpers, function (self, a1::Vector{Any})
    return (j"fn powi(b: f32, n: i32) -> f32 {\n  var r: f32 = 1.0;\n  let m: i32 = abs(n);\n  for (var i: i32 = 0; i < m; i = i + 1) { r = r * b; }\n  if (n < 0) { return 1.0 / r; }\n  return r;\n}\nfn choose(n: f32, k: f32) -> f32 {\n  var r: f32 = 1.0;\n  var i: f32 = 0.0;\n  for (var c: i32 = 0; c < 64; c = c + 1) { if (i < k) { r = r * (n - i) / (i + 1.0); i = i + 1.0; } }\n  return r;\n}\nfn finite(v: f32) -> bool { return abs(v) < 1e30 && v == v; }")
    nothing
  end)
  statik!(c, :points, function (self, a1::Vector{Any})
    points_0 = Any[]
    i_0 = 1.0
    while truthy(le(i_0, 120.0))
      m_push(points_0, rdiv(i_0, 120.0))
      i_0 = add(i_0, 1.0)
    end
    ex_0 = 0.0
    while truthy(le(ex_0, 24.0))
      k_0 = 1.0
      while truthy(lt(k_0, 8.0))
        m_push(points_0, mul((power(10.0, (sub(ex_0, 12.0)))), (add(1.0, rdiv(k_0, 2.0)))))
        k_0 = add(k_0, 1.0)
      end
      ex_0 = add(ex_0, 1.0)
    end
    return rcall(K("Expr"), :sorted, Any[points_0])
    nothing
  end)
  statik!(c, :solver, function (self, a1::Vector{Any})
    name_0 = arg(a1, 0); f_0 = arg(a1, 1)
    pts_0 = rget(K("Shaded"), :points)
    lits_0 = m_join(m_map(pts_0, (function (a3::Vector{Any})
      v_2 = arg(a3, 0)
      return rcall(K("Shaded"), :literal, Any[v_2])
      nothing
    end)), (j", "))
    return (j"const PTS_" * str(name_0) * j": array<f32, " * str(len(pts_0)) * j"> = array<f32, " * str(len(pts_0)) * j">(" * str(lits_0) * j");\nfn " * str(name_0) * j"() -> f32 {\n  var lo: f32 = 0.0;\n  var hi: f32 = 0.0;\n  var found: bool = false;\n  var px: f32 = PTS_" * str(name_0) * j"[0];\n  var pf: f32 = " * str(f_0) * j"(px);\n  for (var j: i32 = 1; j < " * str(len(pts_0)) * j"; j = j + 1) {\n    let cx: f32 = PTS_" * str(name_0) * j"[j];\n    let cf: f32 = " * str(f_0) * j"(cx);\n    if (!found && finite(pf) && finite(cf) && pf * cf <= 0.0) { lo = px; hi = cx; found = true; }\n    px = cx;\n    pf = cf;\n  }\n  if (!found) { return 1e30; }\n  var flo: f32 = " * str(f_0) * j"(lo);\n  for (var n: i32 = 0; n < 60; n = n + 1) {\n    let mid: f32 = (lo + hi) / 2.0;\n    let fm: f32 = " * str(f_0) * j"(mid);\n    if (!finite(fm)) { break; }\n    if (flo * fm <= 0.0) { hi = mid; } else { lo = mid; flo = fm; }\n  }\n  return (lo + hi) / 2.0;\n}")
    nothing
  end)
end

