            if truthy(rnot(((truthy((truthy((truthy(lt(gx_3, 0.0)) || truthy(lt(gy_3, 0.0)))) || truthy(ge(gx_3, rget(self, :XS))))) || truthy(ge(gy_3, rget(self, :YS)))))))
              set_at!(grid_0, add(mul(gy_3, rget(self, :XS)), gx_3), add(elem(grid_0, add(mul(gy_3, rget(self, :XS)), gx_3)), rdiv(1.0, st_2)))
