.x;\n  let per: u32 = P.nB * P.nS * P.RS;\n  if (i >= P.nM * P.nA * per) { return; }\n  let pair: u32 = i / per;\n  let rest: u32 = i % per;\n  let bi: u32 = rest / (P.nS * P.RS);\n  let si: u32 = (rest / P.RS) % P.nS;\n  let k: u32 = rest % P.RS;\n  let mi: u32 = pair / P.nA;\n  let ai: u32 = pair % P.nA;\n  let m: f32 = ax[mi];\n  let A: f32 = ax[P.nM + ai];\n  let beta: f32 = ax[P.nM + P.nA + bi];\n  let S0: f32 = ax[P.nM + P.nA + P.nB + si];\n  " * str(fill_0) * j"\n  " * str(radius_0) * j"\n  " * str(source_0) * j"\n  let gN: f32 = f_arrival();\n  " * str(set_gN_0) * j"\n  " * str(set_a0_0) * j"\n  let g: f32 = f_felt();\n  var lx: f32 = 1e30;\n  var ly: f32 = 1e30;\n  if (finite(gN) && gN > 0.0) { lx = log(gN / " * str(a0_lit_0) * j") / log(10.0); }\n  if (finite(g) && g > 0.0) { ly = log(g / " * str(a0_lit_0) * j") / log(10.0); }\n  xs[i] = lx;\n  ys[i] = ly;\n}")], (j"\n\n"))
