let c = cls("Measure", "Node")
  statik!(c, :save, function (self, a1::Vector{Any})
    id_0 = arg(a1, 0); names_0 = arg(a1, 1); columns_0 = arg(a1, 2); extra_0 = arg(a1, 3)
    rows_0 = len(elem(columns_0, elem(names_0, 0.0)))
    for n_1 in items(names_0)
      if truthy(!eq(len(elem(columns_0, n_1)), rows_0))
        rinvoke(fail, Any[(j"" * str(id_0) * j": " * str(n_1) * j" has " * str(len(elem(columns_0, n_1))) * j" rows where " * str(elem(names_0, 0.0)) * j" has " * str(rows_0) * j"")])
      end
      if truthy(rnot(m_some(elem(columns_0, n_1), (function (a4::Vector{Any})
        v_3 = arg(a4, 0)
        return rcall(K("Fmt"), :finite, Any[v_3])
        nothing
      end))))
        rinvoke(fail, Any[(j"" * str(id_0) * j": column " * str(n_1) * j" is not a number anywhere - the model did not answer, and a field of NaN drawn as a blank panel is worse than a failed run")])
      end
    end
    return rcall(K("Measured"), :save, Any[(j"visuals"), id_0, id_0, names_0, columns_0, extra_0])
    nothing
  end)
  statik!(c, :density, function (self, a1::Vector{Any})
    model_0 = arg(a1, 0); id_0 = arg(a1, 1); how_0 = arg(a1, 2)
    sweep_0 = make("Sweep", Any[kw(:model, model_0), kw(:how, how_0)])
    if truthy((truthy((truthy(eq(rget(sweep_0, :arrival), nothing)) || truthy(eq(rget(sweep_0, :felt), nothing)))) || truthy(eq(rget(sweep_0, :rho_at), nothing))))
      rinvoke(fail, Any[(j"" * str(id_0) * j": nothing derived to integrate")])
    end
    lay_0 = (function (a2::Vector{Any})
      vary_1 = arg(a2, 0)
      got_1 = rcall(sweep_0, :tracks, Any[vary_1])
      return rcall(sweep_0, :rasterise, Any[rget(got_1, Symbol(str((j"xs")))), rget(got_1, Symbol(str((j"ys")))), rget(got_1, Symbol(str((j"tracks"))))])
      nothing
    end)
