    without_0 = m_map(rget(sweep_0, :order), (function (a3::Vector{Any})
      held_2 = arg(a3, 0)
      return rinvoke(lay_0, Any[filt(rget(sweep_0, :order), (function (a5::Vector{Any})
        n_4 = arg(a5, 0)
        return !eq(n_4, held_2)
        nothing
      end))])
      nothing
    end))
    return rcall(sweep_0, :save, Any[id_0, grid_0, rcall(sweep_0, :needs, Any[grid_0, without_0])])
    nothing
  end)
  statik!(c, :law, function (self, a1::Vector{Any})
    model_0 = arg(a1, 0)
    a0_0 = rget(model_0, :a0_lattice)
    gN_0 = Any[]
    g_0 = Any[]
    for i1 in 0:(ceil(Int, num(901.0)) - 1)
      i_1 = Float64(i1)
      x_1 = mul(power(10.0, (add(neg(5.0), rdiv(mul(9.0, i_1), 900.0)))), a0_0)
      m_push(gN_0, x_1)
      m_push(g_0, rcall(model_0, :boost, Any[x_1, a0_0]))
    end
    DEG_0 = rget(rget(rget(model_0, :theory), :lattice), :DEG)
    e_0 = rcall(model_0, :settled, Any[DEG_0])
    rset!(e_0, Symbol(str((j"D"))), rget(rget(rget(model_0, :theory), :lattice), :D))
    rset!(e_0, Symbol(str((j"DEG"))), DEG_0)
