    rset!(symbols_0, Symbol(str((j"DEG"))), DEG_0)
    rset!(symbols_0, Symbol(str((j"\\nu"))), rget(e_0, Symbol(str((j"\\nu")))))
    rset!(symbols_0, Symbol(str((j"\\sigma"))), rget(e_0, Symbol(str((j"\\sigma")))))
    rset!(symbols_0, Symbol(str((j"F"))), rget(e_0, Symbol(str((j"F")))))
    om_0 = rcall(model_0, :value_of, Any[(j"\\omega"), e_0])
    rset!(symbols_0, Symbol(str((j"\\omega"))), (truthy(rcall(K("Fmt"), :finite, Any[om_0])) ? (om_0) : (rget(e_0, Symbol(str((j"\\omega")))))))
