      end
    end
    rset!(symbols_0, Symbol(str((j"\\bar{m}_{x}"))), 1.0)
    columns_0 = make(NODE)
    rset!(columns_0, Symbol(str((j"gN"))), gN_0)
    rset!(columns_0, Symbol(str((j"g"))), g_0)
    extra_0 = make(NODE)
    rset!(extra_0, Symbol(str((j"a0"))), a0_0)
    rset!(extra_0, Symbol(str((j"theory"))), rget(rget(model_0, :theory), :name))
    rset!(extra_0, Symbol(str((j"symbols"))), symbols_0)
    rset!(extra_0, Symbol(str((j"about"))), (j"what arrives against what is felt, both in units of a_0"))
    rset!(extra_0, Symbol(str((j"carries"))), rget(rcall(K("Aggregate"), :of, Any[rget(model_0, :theory), DEG_0, rget(rget(rget(model_0, :theory), :lattice), :D)]), :carries))
    return rcall(K("Measure"), :save, Any[(j"law"), Any[(j"gN"), (j"g")], columns_0, extra_0])
    nothing
  end)
  statik!(c, :run, function (self, a1::Vector{Any})
    theory_0 = arg(a1, 0); only_0 = arg(a1, 1)
    model_0 = make("Model", Any[kw(:theory, theory_0)])
    want_0 = (function (a2::Vector{Any})
      n_1 = arg(a2, 0)
      return (truthy(m_empty(only_0)) || truthy(m_some(only_0, (function (a4::Vector{Any})
        o_3 = arg(a4, 0)
        return m_contains(n_1, o_3)
        nothing
      end))))
      nothing
    end)
    if truthy(rinvoke(want_0, Any[(j"galaxy.point")]))
      rcall(K("Measure"), :density, Any[model_0, (j"galaxy.point"), (j"gathered")])
    end
    if truthy(rinvoke(want_0, Any[(j"galaxy.many")]))
      rcall(K("Measure"), :density, Any[model_0, (j"galaxy.many"), (j"scattered")])
    end
    if truthy(rinvoke(want_0, Any[(j"law")]))
      rcall(K("Measure"), :law, Any[model_0])
    end
    nothing
  end)
end

